/* Apple DNA — pure white, huge tight display type, monochrome with one blue accent */
.theme-apple-dna {
  --bg: oklch(1 0 0);
  --surface: oklch(0.971 0.003 286.4);
  --surface-2: oklch(0.955 0 0);
  --fg: oklch(0.232 0.004 286.1);
  --fg-muted: oklch(0.622 0.007 286.2);
  --accent: oklch(0.563 0.193 256.2);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.669 0.181 251.8);
  --line: oklch(0.9 0 0);
  --success: oklch(0.66 0.16 150);
  --warning: oklch(0.8 0.15 80);
  --danger: oklch(0.6 0.22 25);

  --radius: 0.75rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px oklch(0 0 0 / 5%);
  --shadow-2: 0 8px 24px -8px oklch(0 0 0 / 12%);
  --shadow-3: 0 30px 70px -30px oklch(0 0 0 / 25%);
  --glow: 0 0 0 4px color-mix(in oklab, var(--accent) 25%, transparent);

  --border-width: 1px;
  --blur-amount: 20px;

  --font-display: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", sans-serif;
  --font-body: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.045em;
  --label-transform: none;
  --label-tracking: 0em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-apple-dna h1,
.theme-apple-dna h2,
.theme-apple-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 700;
  line-height: 1.03;
}

.theme-apple-dna h1 {
  font-size: clamp(3rem, 7vw, 5.5rem);
}

.theme-apple-dna button {
  border-radius: var(--radius-pill);
  font-weight: 500;
}

/* signature */
.theme-apple-dna h1 { font-weight: 700; }
.theme-apple-dna button { font-size: 0.95em; }
.theme-apple-dna ::selection { background: oklch(0.7 0.15 255 / 30%); }

/* depth */
.theme-apple-dna thead th { font-size: 0.75rem; font-weight: 600; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-apple-dna td { border-bottom: 1px solid color-mix(in oklab, var(--line) 55%, transparent); }
.theme-apple-dna tbody tr:hover { background: var(--surface); }
.theme-apple-dna a { color: var(--accent); text-decoration: none; }
.theme-apple-dna a:hover { text-decoration: underline; }
.theme-apple-dna input, .theme-apple-dna select, .theme-apple-dna textarea { background: var(--surface); border: 1px solid transparent; border-radius: var(--radius); transition: background 150ms ease, box-shadow 150ms ease; }
.theme-apple-dna input:focus-visible, .theme-apple-dna select:focus-visible, .theme-apple-dna textarea:focus-visible { outline: none; background: var(--bg); border-color: var(--accent-2); box-shadow: var(--glow); }
.theme-apple-dna kbd { font-family: var(--font-body); background: var(--surface); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 0.375rem; padding: 0.1em 0.45em; font-size: 0.8em; }
.theme-apple-dna dialog { backdrop-filter: blur(var(--blur-amount)) saturate(180%); -webkit-backdrop-filter: blur(var(--blur-amount)) saturate(180%); }
.theme-apple-dna button { transition: transform 150ms ease, opacity 150ms ease; }
.theme-apple-dna button:active { transform: scale(0.97); opacity: 0.85; }
.theme-apple-dna ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-apple-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-apple-dna ::-webkit-scrollbar-thumb { background: oklch(0 0 0 / 25%); border-radius: 999px; }
.theme-apple-dna .label-caps { font-size: 0.6875rem; letter-spacing: 0.08em; color: var(--fg-muted); }
.theme-apple-dna .themed-border { border-color: var(--line); border-radius: var(--radius-lg); }

/* alt mode: product-page black — #000 stage, #1d1d1f cards, #2997ff blue */
.theme-apple-dna.alt-mode {
  --bg: oklch(0.050 0 0);
  --surface: oklch(0.160 0 0);
  --surface-2: oklch(0.210 0 0);
  --fg: oklch(0.960 0 0);
  --fg-muted: oklch(0.630 0 0);
  --accent: oklch(0.662 0.170 252.0);
  --line: oklch(1 0 0 / 16%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-apple-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(1 0 0 / 30%); }
.theme-apple-dna.alt-mode ::selection { background: oklch(0.67 0.17 252 / 40%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
